#define NUM_POINTS 32
#define MAX_ITER 10
#define PI 3.14159265359

float sdLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}


float S(float v) {
    vec2 r = vec2(iResolution.x, iResolution.y);
    float aa_width = 1.5/r.y;
    return smoothstep(aa_width, 0.0, v);
}

float map(in vec2[NUM_POINTS] v, in vec2 p) {
    float d = 9999.0;

    for(int i=0; i<NUM_POINTS; i++) {
        vec2 w = p - v[i];
        d = min(d, dot(w, w));
    }


    return sqrt(d);
}

vec2 findNearest(vec2 query, vec2[NUM_POINTS] points) {
    float minDist = 1000.0;
    vec2 nearest = points[0];

    for(int i = 0; i < NUM_POINTS; i++) {
        vec2 p = points[i];
        float dist = length(query - p);
        if(dist < minDist) {
            minDist = dist;
            nearest = p;
        }
    }
    return nearest;
}

float computeRadius(vec2 p, vec2 n, vec2 q) {
    vec2 v = q - p;
    float d = length(v);

    // Early exit for very close points
    if(d < 1e-6) return 0.1;

    float cos_theta = dot(n, v) / d;

    // Handle near-perpendicular case
    if(abs(cos_theta) < 1e-6) return 0.1;

    float r = d / (2.0 * cos_theta);

    // Clamp radius to reasonable bounds
    return clamp(r, 0.01, 1.0);
}

vec2 computeNextBallCenter(vec2 p, vec2 qnext, vec2 n) {
    float rnext = computeRadius(p, n, qnext);

    return p + n * rnext;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
   vec3 COLOR_BACKGROUND = vec3(0.8);
   vec3 COLOR_POLYGON = vec3(0.5); 
   vec3 COLOR_BALL = vec3(0.9);
   vec3 COLOR_CENTER_POINT = vec3(1.0);
   vec3 COLOR_ACTIVE = vec3(1.0, 0.5, 0.0);
   vec3 COLOR_ARROW = COLOR_POLYGON;

   float SIZE = 0.01;

   vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
   vec3 col = COLOR_BACKGROUND;

   // Generate vertices
   vec2[NUM_POINTS] vertices;
   for(int i = 0; i < NUM_POINTS; i++) {
       float angle = float(i) * 2.0 * PI / float(NUM_POINTS);
       vertices[i] = vec2(
           cos(angle) * 0.3 - sin(angle * 0.5) * 0.5 + 0.5 * 0.5,
           sin(angle) * 0.25 + cos(angle * 7.0 - 0.5 - angle * angle * 0.2) * 0.04
       );
   }

   // Draw base shape
   float d = map(vertices, uv);
   col = mix(COLOR_POLYGON, col, 1.0 - S(abs(d) - SIZE * 0.5));

   for(int i = 0; i < NUM_POINTS; i++) {
       vec2 p = vertices[i];
       vec2 p0 = vertices[int(mod(float(i+1), float(NUM_POINTS)))];
       vec2 e = normalize(p0 - p);
       vec2 n = vec2(-e.y, e.x);

       // Draw arrow for normal vector
       float arrowDist =  sdLine(uv,  p, p + n * 0.025);
       col = mix(col, COLOR_ARROW, S(arrowDist - SIZE * 0.1));
   }

   // Animation control - looped
   float loopDuration = float(NUM_POINTS);
   float time = mod(iTime * 4.0, loopDuration);
   int currentPoint = int(time);
   float fadeProgress = fract(time);

   // Process vertices up to current point
   for(int i = 0; i <= currentPoint; i++) {
       vec2 p = vertices[i];
       vec2 p0 = vertices[int(mod(float(i+1), float(NUM_POINTS)))];
       vec2 e = normalize(p0 - p);
       vec2 n = vec2(-e.y, e.x);

       // Draw active surface point in orange
       if(i == currentPoint) {
           float pointDot = length(uv - p);
           col = mix(col, COLOR_ACTIVE, S(pointDot - SIZE * 1.0));
       }

       float r = 0.4;
       vec2 c = p + n * r;

       // Find final medial ball
    for(int iter = 0; iter < MAX_ITER; iter++) {
        vec2 qnext = findNearest(c, vertices);



        vec2 cnext = computeNextBallCenter(p, qnext, n);
        float rnext = length(cnext - p);

        // Check if we converged or if radius becomes invalid
        if(abs(rnext - r) < 1e-6 || rnext < 0.01 || rnext > 1.0) {
            float alpha = (i == currentPoint) ? fadeProgress : 0.75;

            // Draw final medial ball
            float ballDist = abs(length(uv - c) - r);
            col = mix(col, COLOR_BALL, alpha * S(ballDist - SIZE * 0.1));

            // Draw center point
            float centerDot = length(uv - c);
            col = mix(col, COLOR_CENTER_POINT, alpha * S(centerDot - SIZE));
            break;
        }

        c = cnext;
        r = rnext;
    }
   }

   fragColor = vec4(col, 1.0);
}
